function maximumDifference(nums) {
  let smallest = nums[0];
  let best = -1;
  for (let j = 1; j < nums.length; j++) {
    if (nums[j] > smallest) {
      best = Math.max(best, nums[j] - smallest);
    } else {
      smallest = nums[j];
    }
  }
  return best;
}

