function maximumDifference(nums) {
  let answer = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (nums[i] < nums[j] && nums[j] - nums[i] > answer) answer = nums[j] - nums[i];
