function generate(rand, size) {
  const n = size === 'large' ? 1000 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' ? 1000000000 : (rand() < 0.5 ? 5 : 100);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const shape = rand();
  // Sometimes make the array non-increasing so that no valid pair exists.
  if (shape < 0.25) nums.sort((a, b) => b - a);
  else if (shape < 0.35) nums.sort((a, b) => a - b);
  return [nums];
}
